async function captureBackup(file){try{state.flavor=flavor();state.file=file;state.raw=new Uint8Array(await file.arrayBuffer());state.data=await decodeFile(file,state.flavor);state.original=clone(state.data);indexes();state.selected.clear();state.cover.clear();pushLog(`Loaded ${file.name} into v1.6 working copy`);snapshot(false);updateSuiteStatus();repairLibraryCovers();toast(`v1.6 suite ready · ${state.data.backupManga.length.toLocaleString()} manga`)}catch(e){console.warn('Kirin v1.6 suite decode:',e);toast(`Suite decode: ${e.message}`)}}
