function integrity(){if(!state.data)return {grade:'—',score:0,broken:0,unknown:0,dupes:0,orphan:0};const m=A(state.data.backupManga);let broken=0,unknown=0,orphan=0;const seen=new Set(),dupes=[];m.forEach(x=>{A(x.categories).forEach(c=>{if(!state.catMap.has(S(c)))broken++});if(!state.sourceMap.has(S(x.source)))unknown++;const urls=new Set(A(x.chapters).map(c=>S(c.url)));orphan+=A(x.history).filter(h=>!urls.has(S(h.url))).length;const k=key(x);if(seen.has(k))dupes.push(k);else seen.add(k)});const cost=broken*2+unknown*3+dupes.length*3+orphan*.1;const score=Math.max(0,Math.round(100-cost/Math.max(1,m.length*2)*100));return {grade:score>=95?'A':score>=85?'B':score>=70?'C':score>=55?'D':'F',score,broken,unknown,dupes:dupes.length,orphan}}
