function renderCollections(){const pins=A(state.data.backupManga).filter(m=>state.pins.has(key(m))),names=Object.keys(state.collections);$('#kvx-body').innerHTML=`<div class="kvx-toolbar"><button class="kvx-btn primary" data-kvx-action="select-filtered">Select visible main-library page</button><button class="kvx-btn" data-kvx-action="new-collection">New collection</button></div><div class="kvx-grid two"><section class="kvx-panel"><h3>Pinned manga</h3><div class="kvx-list">${pins.length?pins.slice(0,100).map(m=>selectRow(m)).join(''):'<div class="kvx-empty">No local pins yet.</div>'}</div></section><section class="kvx-panel"><h3>Local collections</h3><div class="kvx-list">${names.length?names.map(n=>row(n,'Stored locally in this browser',A(state.collections[n]).length.toLocaleString())).join(''):'<div class="kvx-empty">No local collection yet.</div>'}</div></section></div><section class="kvx-panel"><h3>Bulk library</h3><div class="kvx-toolbar"><input id="kvx-bulk-search" class="kvx-input" placeholder="Search manga for bulk actions…"></div><div id="kvx-bulk-list" class="kvx-list"></div></section><div id="kvx-selection" class="kvx-selection-bar"></div>`;const draw=()=>{const q=norm($('#kvx-bulk-search').value);const list=A(state.data.backupManga).filter(m=>!q||norm(`${title(m)} ${source(m)}`).includes(q)).slice(0,300);$('#kvx-bulk-list').innerHTML=list.map(m=>selectRow(m)).join('');renderSelectionBar()};$('#kvx-bulk-search').addEventListener('input',draw);draw()}
